name: PR Issue Link Check

on:
  pull_request:
    types: [opened, synchronize, reopened, edited]
  merge_group:
    types: [checks_requested]

permissions:
  issues: read
  pull-requests: read

jobs:
  check-pr-links:
    runs-on: ubuntu-latest
    steps:
      - name: Check PR Description for Issue Links
        id: check_description
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = context.payload.pull_request.number;
            const prTitle = context.payload.pull_request.title;
            const prBody = context.payload.pull_request.body || '';

            // Define regex patterns for issue references
            const patterns = [
              /(?:fix|fixes|closed|closes|resolves|resolve)\s+#(\d+)/gi,
              /(?:fix|fixes|closed|closes|resolves|resolve)\s+issue\s+#(\d+)/gi,
              /(?:fix|fixes|closed|closes|resolves|resolve)\s+(?:#\d+\s*,?\s*)+/gi
            ];

            let issueNumbers = [];
            let foundInDescription = false;
            let foundInTitle = false;

            // Check PR description
            for (const pattern of patterns) {
              const matches = [...prBody.matchAll(pattern)];
              for (const match of matches) {
                if (match[1]) {
                  issueNumbers.push(parseInt(match[1]));
                  foundInDescription = true;
                }
              }
            }

            // Check PR title
            for (const pattern of patterns) {
              const matches = [...prTitle.matchAll(pattern)];
              for (const match of matches) {
                if (match[1]) {
                  issueNumbers.push(parseInt(match[1]));
                  foundInTitle = true;
                }
              }
            }

            // Remove duplicates
            issueNumbers = [...new Set(issueNumbers)];

            // If no issue numbers found, fail the check
            if (issueNumbers.length === 0) {
              core.setFailed('No issue reference found in PR title or description. Please reference an issue using "Fixes #123", "Closes #456", or "Resolves #789".');
              return;
            }

            // Validate each issue exists
            for (const issueNumber of issueNumbers) {
              try {
                const response = await github.rest.issues.get({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: issueNumber
                });

                if (response.status !== 200) {
                  core.setFailed(`Issue #${issueNumber} does not exist.`);
                  return;
                }
              } catch (error) {
                core.setFailed(`Issue #${issueNumber} does not exist.`);
                return;
              }
            }

            // Log success
            core.info(`Validated PR #${prNumber} links to issues: ${issueNumbers.join(', ')}`);

            // Set outputs
            core.setOutput('issue_numbers', issueNumbers.join(','));
            core.setOutput('found_in_description', foundInDescription);
            core.setOutput('found_in_title', foundInTitle);
```

